export function getGroupName(t){return t?.groupName??t?.group??t?.category??null}export function getMoneyLimit(t){return t?.moneyLimit??t?.money_limit??null}export function getCreatedAt(t){return t?.createdAt??t?.date??null}function findById(t,e){return Array.isArray(t)&&null!=e&&t.find(t=>String(t.id)===String(e))||null}function isPurchaseRequest(t){return"shop_purchase"===t?.requestType}function getRequestItem(t,e){return findById(e?.shopItems,t?.itemId??t?.taskId)}function getRequestTask(t,e){return findById(e?.tasks,t?.taskId)}export function getRequestGroup(t,e){const r=t?.itemGroup??t?.taskGroup??t?.group??null;if(r)return r;return getGroupName(isPurchaseRequest(t)?getRequestItem(t,e):getRequestTask(t,e))}export function getRequestComment(t,e){const r=t?.taskComment??t?.comment??null;if(r)return r;const n=isPurchaseRequest(t)?getRequestItem(t,e):getRequestTask(t,e);return n?.comment??null}export function normalizeChild(t={}){return{...t,monthlyLimit:t.monthlyLimit??t.monthly_limit??1e4,dailyCoinLimit:t.dailyCoinLimit??t.daily_coin_limit??0}}export function normalizeTask(t={}){return{...t,groupName:t.groupName??t.group??null,moneyLimit:t.moneyLimit??t.money_limit??null}}export function normalizeShopItem(t={}){return{...t,groupName:t.groupName??t.group??null,moneyLimit:t.moneyLimit??t.money_limit??null}}export function normalizeHistoryEntry(t={}){return{...t,groupName:t.groupName??t.group??null,createdAt:getCreatedAt(t)}}export function normalizeRequest(t={}){return{...t,createdAt:getCreatedAt(t),taskGroup:t.taskGroup??t.group??null,itemGroup:t.itemGroup??t.group??null,taskComment:t.taskComment??t.comment??null}}export function normalizeServerData(t={}){return{...t,tasks:Array.isArray(t.tasks)?t.tasks.map(normalizeTask):[],shop:Array.isArray(t.shop)?t.shop.map(normalizeShopItem):[],history:Array.isArray(t.history)?t.history.map(normalizeHistoryEntry):[],requests:Array.isArray(t.requests)?t.requests.map(normalizeRequest):[],children:Array.isArray(t.children)?t.children.map(normalizeChild):[]}}